window.AUTH=window.AUTH||{};window.AUTH["23-7483"]={"d":"23-7483","id":"2024/23-7483","n":"Esteras v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Edgardo Esteras","date":"2024-12-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-7483/334708/20241210070551859_No.%2023-7483_Brief%20for%20the%20Petitioners.pdf","side":"pet","n":31},{"k":"respondent","label":"Brief of respondent United States","date":"2025-01-15","url":"https://www.supremecourt.gov/DocketPDF/23/23-7483/337388/20250115171916052_23-7483bsUnitedStates.pdf","side":"res","n":90},{"k":"reply","label":"Reply of petitioner Edgardo Esteras","date":"2025-02-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-7483/342044/20250205141721232_No.%2023-7483_Reply%20Brief.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r56_bq7d.pdf","tr":true,"items":[{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"0":"19, 20, 21","2":"3"},"q":[{"src":"brief","b":0,"text":"When Congress includes particular language in one section of a statute but omits it from a neighbor, [this Court] normally understand[s] that difference in language to convey a difference in meaning (expressio unius est exclusio alterius).","cite":"598 U.S. 85, 94"},{"src":"argument","who":"Mr. Grostic","text":"The second, as this Court said in -- for example, in Bittner, when Congress includes language in one statute but omits it in a neighbor, that also brings the negative implication canon to the fore."}]},{"t":"case","label":"Concepcion v. United States","cite":"597 U.S. 481","y":2022,"id":"2021/20-1650","sc":1,"by":{"0":"18, 21, 33","1":"21, 22, 42, 43"},"q":[{"src":"brief","b":0,"text":"Congress could not have expected courts to wipe their minds of these concerns when they move from one type of sentence to the other.","cite":"597 U.S. at 495"},{"src":"brief","b":1,"text":"characterizes federal sentencing history as well.","cite":"597 U.S. at 492"},{"src":"brief","b":1,"text":"carries forward to later proceedings that may modify an original sentence.","cite":"597 U.S. at 491"},{"src":"opinion","who":"Justice Sotomayor, concurring in part and concurring in the judgment","text":"Congress has expressly precluded district courts from considering the need for retribution","cite":"597 U. S. 481, 494"},{"src":"opinion","who":"Justice Alito, dissenting","text":"the established tradition of district courts' sentencing discretion.","cite":"597 U. S. 481, 495"},{"src":"argument","who":"Ms. Hansford","text":"That is the background rule reflected in 3661 and decisions like Kimbrough and Concepcion. So I think it would be a little bit of a different situation if this was what was giving courts authority in that particular thing."},{"src":"argument","who":"Mr. Grostic","text":"It's what -- it Congress said it was doing in the Senate report. It's what this Court observed in Concepcion and Tapia. And we'd ask the Court to reverse the judgments below on that basis."}]},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Ret. Fund","cite":"583 U.S. 416","y":2018,"id":"2017/15-1439","sc":1,"by":{"0":"18, 30"},"q":[{"src":"brief","b":0,"text":"The statute says what it says—or perhaps better put here, does not say what it does not say.","cite":"583 U.S. 416, 426"},{"src":"brief","b":0,"text":"say[ ] what it says—or perhaps better put here . . . not say what it does not say.","cite":"583 U.S. at 426"}]},{"t":"case","label":"Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"by":{"0":"20, 25"},"q":[{"src":"brief","b":0,"text":"a unique method of post-confinement supervision.","cite":"498 U.S. at 407"},{"src":"argument","who":"Mr. Grostic","text":"And I -- I'd start with what this Court has said in numerous cases -- in Granderson, in Roy Lee Johnson, in Gozlon-Peretz -- that supervised release was created for different purposes, both different purposes than parole that came before and different purposes than a prison sentence that it precedes."}]},{"t":"case","label":"Int’l Union, Mine Works of Am. v. Bagwell","cite":"512 U.S. 821","y":1994,"id":"1993/92-1625","sc":1,"by":{"0":"28"}},{"t":"case","label":"Iselin v. United States","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"‘To supply omissions transcends the judicial function.’","cite":"270 U.S. at 251"}]},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"by":{"0":"31, 32","1":"3, 4, 33, 34, 40, 47"},"q":[{"src":"brief","b":0,"text":"[w]here the acts of violation are criminal in their own right, they may be the basis for separate prosecution, which would raise an issue of double jeopardy if the revocation of supervised release were also punishment for the same offense.","cite":"529 U.S. at 700"},{"src":"brief","b":1,"text":"attribute[d] * * * to the original conviction.","cite":"529 U.S. at 701"}]},{"t":"case","label":"Kungys v. United States","cite":"485 U.S. 759","y":1988,"id":"1986/86-228","sc":1,"by":{"0":"34"}},{"t":"case","label":"Lora v. United States","cite":"599 U.S. 453","y":2023,"id":"2022/22-49","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"must implement the design Congress chose.","cite":"599 U.S. 453, 464"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"23, 24","1":"3, 25"},"q":[{"src":"brief","b":0,"text":"Both indeterminate sentencing and parole were based on concepts of the offender’s possible, indeed probable, rehabilitation, a view that it was realistic to attempt to rehabilitate the inmate and thereby to minimize the risk that he would resume criminal activity upon his return to society.","cite":"488 U.S. at 364"}]},{"t":"case","label":"Cited Authorities Page Nat’l R.R. Passenger Corp. v. Nat’l Ass’n of R.R. Passengers","cite":"414 U.S. 453","y":1974,"id":"1973/72-1289","sc":1,"by":{"0":"19","2":"5"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"‘is not a construction of the statute, but, in effect, an enlargement of it by the court.’","cite":"578 U.S. 104, 110"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"It is a fundamental principle of statutory interpretation that ‘absent provision[s] cannot be supplied by the courts.’","cite":"589 U.S. 8, 14"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"20, 22","1":"24"},"q":[{"src":"brief","b":0,"text":"Congress includes particular language in one section of a statute but omits it in another section of the same Act.","cite":"464 U.S. 16, 23"},{"src":"brief","b":0,"text":"refrain from concluding here that the differing language in the two [provisions] has the same meaning in each.","cite":"464 U.S. at 23"},{"src":"opinion","who":"Justice Alito, dissenting","text":"Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U. S. 16, 23"}]},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"by":{"0":"7, 17, 18, 23, 24, 33, 34, 18","1":"28, 42","2":"1, 11-14, 16, 18, 12, 13"},"q":[{"src":"brief","b":0,"text":"the four purposes of sentencing generally.","cite":"564 U.S. 319, 325"},{"src":"brief","b":0,"text":"Lawmakers and others increasingly doubted that prison programs could ‘rehabilitate individuals on a routine basis’—or that parole officers could ‘determine accurately whether or when a particular prisoner had been rehabilitated.’","cite":"564 U.S. at 324"},{"src":"brief","b":2,"text":"Section 3583(c) explicitly lists each Section 3553(a) factor that courts must consider and omits the factors whose consideration Congress intended to preclude. See 18 U.S.C. 3583(c).","cite":"564 U.S. 319"},{"src":"brief","b":2,"text":"Section 3583(c) removes multiple Section 3553(a) factors from consideration (Section 3553(a)(2)(A) and Section 3553(a)(3)).","cite":"564 U.S. 319"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"These four considerations—retribution, deterrence, incapacitation, and rehabilitation—are the four purposes of senin their revocation proceedings had improperly considered § 3553(a)(2)(A). The Sixth Circuit held that these arguments were foreclosed by Esteras and Lewis. See United States v. Jaimez, 95 F. 4th 1004, 1007 (2024); United States v. Leaks, 2024 WL 2196795, *1 (Mar. 6, 2024). tencing generally.","cite":"564 U. S. 319, 325"},{"src":"argument","who":"Mr. Grostic","text":"Congress thereby precluded courts from considering (a)(2)(A)'s retributive purposes in the supervised release context, as this Court recognized in Tapia regarding the identical list in subsection (c)."},{"src":"argument","who":"Mr. Grostic","text":"But the -- the -- the words that a court uses in this context are for a purpose, and (a)(2)(A)'s purpose, as this Court again recognized in Tapia, was about that -- retributive purpose."},{"src":"argument","who":"Mr. Grostic","text":"-- in Tapia, this Court did not say that that was an outright bar on considering that factor actually."}]},{"t":"case","label":"United States v. Booker","cite":"63 F.4th 1254","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/63/1254/","by":{"0":"19","1":"38","2":"15"}},{"t":"case","label":"United States v. Burden","cite":"860 F.3d 45","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/860/45/","by":{"0":"33","2":"14"}},{"t":"case","label":"United States v. Crudup","cite":"461 F.3d 433","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/461/433/","by":{"0":"19"}},{"t":"case","label":"United States v. Esteras","cite":"88 F.4th 1163","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/1163/","by":{"0":"1, 11, 12"}},{"t":"case","label":"United States v. Esteras","cite":"88 F.4th 1170","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/1170/","by":{"0":"1"}},{"t":"case","label":"Cited Authorities Page United States v. Esteras","cite":"95 F.4th 454","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/95/454/","by":{"0":"1"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"27, 28"},"q":[{"src":"argument","who":"Mr. Grostic","text":"And I -- I'd start with what this Court has said in numerous cases -- in Granderson, in Roy Lee Johnson, in Gozlon-Peretz -- that supervised release was created for different purposes, both different purposes than parole that came before and different purposes than a prison sentence that it precedes."}]},{"t":"case","label":"United States v. Haymond","cite":"588 U.S. 634","y":2019,"id":"2018/17-1672","sc":1,"by":{"0":"24, 25, 27, 31","1":"46, 47"},"q":[{"src":"brief","b":0,"text":"overhauled federal sentencing procedures to make prison terms more determinate and abolish the practice of parole.","cite":"588 U.S. 634, 651"},{"src":"brief","b":0,"text":"supervised release wasn’t introduced to replace a portion of the defendant’s prison term, only to encourage rehabilitation after the completion of his prison term.","cite":"588 U.S. at 652"},{"src":"argument","who":"Justice Gorsuch","text":"We dealt with that in Haymond, for example, right? We're now dealing in the context of supervised release. And it just -- and magic words, I -- I appreciate some words are important, but I -- I -- I -- I struggle with synonyms."}]},{"t":"case","label":"United States v. Jaimez","cite":"95 F.4th 1004","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/95/1004/","by":{"0":"1"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"by":{"0":"8, 25","1":"45"},"q":[{"src":"brief","b":0,"text":"[w]here the acts of violation are criminal in their own right, they may be the basis for separate prosecution, which would raise an issue of double jeopardy if the revocation of supervised release were also punishment for the same offense.","cite":"529 U.S. at 700"},{"src":"brief","b":1,"text":"distinct from those served by incarceration.","cite":"529 U.S. 53, 59"},{"src":"brief","b":1,"text":"attribute[d] * * * to the original conviction.","cite":"529 U.S. at 701"},{"src":"opinion","who":"Justice Sotomayor, concurring in part and concurring in the judgment","text":"`ful- Opinion of Jackson, J. flls rehabilitative ends' and `provides individuals with postconfnement assistance.'","cite":"529 U. S. 53, 59–60"},{"src":"opinion","who":"Justice Alito, dissenting","text":"[s]upervised release fulflls [its] rehabilitative ends.","cite":"529 U. S. 53, 59"}]},{"t":"case","label":"United States v. Lewis","cite":"498 F.3d 393","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/498/393/","by":{"0":"10, 11, 12","2":"14"},"q":[{"src":"brief","b":0,"text":"‘it does not constitute reversible error to consider § 3553(a)(2)(A) when imposing a sentence for violation of supervised release, even though this factor is not enumerated in § 3583(e).’","cite":"498 F.3d at 399"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[t]o think about the one requires the judge to think about the other.","cite":"498 F. 3d, at 400"}]},{"t":"case","label":"United States v. Miller","cite":"634 F.3d 841","y":2011,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/841/","by":{"0":"19"}},{"t":"case","label":"United States v. Miqbel","cite":"444 F.3d 1173","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1173/","by":{"0":"19, 34","1":"37","2":"14, 16, 17"},"q":[{"src":"brief","b":1,"text":"intertwined with the concept of punishment.","cite":"444 F.3d 1173, 1182"}]},{"t":"case","label":"United States v. Wilcher","cite":"91 F.4th 864","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/91/864/","by":{"0":"33","2":"14"}},{"t":"case","label":"Williams v. Illinois","cite":"567 U.S. 50","y":2012,"id":"2011/10-8505","sc":1,"by":{"0":"33"}},{"t":"case","label":"Biden v. Texas","cite":"597 U.S. 785","y":2022,"id":"2021/21-954","sc":1,"by":{"1":"25"}},{"t":"case","label":"Burns v. United States","cite":"501 U.S. 129","y":1991,"id":"1990/89-7260","sc":1,"by":{"1":"30"}},{"t":"case","label":"Campos-Chaves v. Garland","cite":"602 U.S. 447","y":2024,"id":"2023/22-674","sc":1,"by":{"1":"43"}},{"t":"case","label":"Christensen v. Harris County","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"by":{"1":"30"}},{"t":"case","label":"Dean v. United States","cite":"581 U.S. 62","y":2017,"id":"2016/15-9260","sc":1,"by":{"1":"22, 27"},"q":[{"src":"brief","b":1,"text":"Congress has shown that it knows how to direct sentencing practices in express terms.","cite":"581 U.S. at 70"}]},{"t":"case","label":"Entergy Corp. v. Riverkeeper, Inc.","cite":"556 U.S. 208","y":2009,"id":"2008/07-588","sc":1,"by":{"1":"31"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"1":"45"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"1":"43"},"q":[{"src":"opinion","who":"Justice Alito, dissenting","text":"[d]ictum settles nothing, even in the court that utters it.","cite":"543 U. S. 335, 351, n. 12"}]},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"by":{"1":"21, 27, 30"},"q":[{"src":"brief","b":1,"text":"to read any implicit directive into * * * congressional silence","cite":"552 U.S. 85, 103"},{"src":"argument","who":"Ms. Hansford","text":"That is the background rule reflected in 3661 and decisions like Kimbrough and Concepcion. So I think it would be a little bit of a different situation if this was what was giving courts authority in that particular thing."}]},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"read an absent word into the statute.","cite":"540 U.S. 526, 538"}]},{"t":"case","label":"Luna Perez v. Sturgis Pub. Sch.","cite":"598 U.S. 142","y":2023,"id":"2022/21-887","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"no law ‘pursues its purposes at all costs.’","cite":"598 U.S. 142, 150"}]},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"1":"23, 30"}},{"t":"case","label":"Miller v. Youakim","cite":"440 U.S. 125","y":1979,"id":"1978/77-742","sc":1,"by":{"1":"24"}},{"t":"case","label":"Mont v. United States","cite":"587 U.S. 514","y":2019,"id":"2018/17-8995","sc":1,"by":{"1":"3, 40"},"q":[{"src":"brief","b":1,"text":"facilitate[s] a transition to community life","cite":"587 U.S. 514, 523"},{"src":"brief","b":1,"text":"facilitate[s] a ‘transition to community life,’","cite":"587 U.S. 514, 523"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"Supervised release is `a form of postconfnement monitoring' that permits a defendant a kind of conditional liberty by allowing him to serve part of his sentence outside of prison,","cite":"587 U. S. 514, 523"}]},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"by":{"1":"46"}},{"t":"case","label":"Pension Benefit Guaranty Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"several equally tenable inferences may be drawn.","cite":"496 U.S. 633, 650"}]},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"1":"22"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil Grp., Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"Congress has (as here) included the term in question elsewhere in the very same statutory provision.","cite":"590 U.S. 212, 215"}]},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"1":"28"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"by":{"1":"24"}},{"t":"case","label":"United States v. Sanchez","cite":"900 F.3d 678","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/678/","by":{"1":"38","2":"16"}},{"t":"case","label":"United States v. Simtob","cite":"485 F.3d 1058","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/485/1058/","by":{"1":"37"}},{"t":"case","label":"United States v. Vargas-Dávila","cite":"649 F.3d 129","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/649/129/","by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"substantially overlap with section 3553(a)(2)(A)’s instruction ‘to promote respect for the law.’","cite":"649 F.3d 129, 131-132"}]},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"one item of a commonly associated group or series excludes another left unmentioned,","cite":"535 U.S. 55, 65"}]},{"t":"case","label":"United States v. Webb","cite":"738 F.3d 638","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/638/","by":{"1":"33"}},{"t":"case","label":"United States v. Williams","cite":"443 F.3d 35","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/35/","by":{"1":"37"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"20, 46, 47"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4466","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"1":"43"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(B)","(a)(2)(C)","(a)(2)(D)","(a)(3)","(a)(4)(A)","(a)(4)(B)","(a)(5)","(a)(5)(A)","(a)(6)","(a)(7)","(b)(1)","(b)(2)","(a)(4)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"1":"5, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 17, 28, 34, 28","2":"3, 9, 12, 16, 3, 8, 9, 1, 11, 12, 16, 1-4, 6-8, 10, 13-18, 3, 8, 9, 3, 8, 9, 17, 3, 8, 9, 13, 3, 8, 9, 3, 8, 9, 3, 8, 9, 3, 8, 9"},"q":[{"src":"brief","b":1,"text":"court, in determining the particular sentence to be imposed, shall consider.","cite":"18 U.S.C. 3553(a)"},{"src":"brief","b":1,"text":"the history and characteristics of the defendant,","cite":"18 U.S.C. 3553(a)(1)"},{"src":"brief","b":2,"text":"the need for the sentence imposed . . . to reflect the seriousness of the offense,","cite":"18 U.S.C. § 3553(a)(2)(A)"},{"src":"brief","b":2,"text":"the need for the sentence imposed . . . to protect the public from further crimes of the defendant,","cite":"18 U.S.C. § 3553(a)(2)(C)"}]},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(c)(3)(A)"],"by":{"1":"28"}},{"t":"usc","label":"18 U.S.C. § 3562","url":"https://www.law.cornell.edu/uscode/text/18/3562","subs":["(a)"],"stext":{"head":"§3562. Imposition of a sentence of probation","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Probation.—The court, in determining whether to impose a term of probation, and, if a term of probation is to be imposed, in determining the length of the term and the conditions of probation, shall consider the factors set forth in section 3553(a) to the extent that they are applicable."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence of probation can subsequently be—"],[1,"(1) modified or revoked pursuant to the provisions of section 3564 or 3565;"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3562?type=usc&year=mostrecent&link-type=html"},"by":{"1":"17, 29, 35","2":"7, 9"},"q":[{"src":"brief","b":1,"text":"consider the factors set forth in section 3553(a) to the extent that they are applicable,","cite":"18 U.S.C. 3562(a), 3582"}]},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)","(b)(10)"],"stext":{"head":"§3563. Conditions of probation","paras":[[0,"(a) Mandatory Conditions.—The court shall provide, as an explicit condition of a sentence of probation—"],[1,"(1) for a felony, a misdemeanor, or an infraction, that the defendant not commit another Federal, State, or local crime during the term of probation;"],[1,"(2) for a felony, that the defendant also abide by at least one condition set forth in subsection (b)(2) or (b)(12), unless the court has imposed a fine under this chapter, or unless the court finds on the record that extraordinary circumstances exist that would make such a condition plainly unreasonable, in which event the court shall impose one or more of the other conditions set forth under subsection (b);"],[1,"(3) for a felony, a misdemeanor, or an infraction, that the defendant not unlawfully possess a controlled substance;"],[1,"(4) for a domestic violence crime as defined in section 3561(b) by a defendant convicted of such an offense for the first time that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant;"],[1,"(5) for a felony, a misdemeanor, or an infraction, that the defendant refrain from any unlawful use of a controlled substance and submit to one drug test within 15 days of release on probation and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance, but the condition stated in this paragraph may be ameliorated or suspended by the court for any individual defendant if the defendant's presentence report or other reliable sentencing information indicates a low risk of future substance abuse by the defendant;"],[1,"(6) that the defendant—"],[2,"(A) make restitution in accordance with sections 2248, 2259, 2264, 2327, 3663, 3663A, and 3664; and"],[2,"(B) pay the assessment imposed in accordance with section 3013;"],[1,"(7) that the defendant will notify the court of any material change in the defendant's economic circumstances that might affect the defendant's ability to pay restitution, fines, or special assessments;"],[1,"(8) for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act; and"],[1,"(9) that the defendant cooperate in the collection of a DNA sample from the defendant if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000."],[0,"If the court has imposed and ordered execution of a fine and placed the defendant on probation, payment of the fine or adherence to the court-established installment schedule shall be a condition of the probation."],[0,"(b) Discretionary Conditions.—The court may provide, as further conditions of a sentence of probation, to the extent that such conditions are reasonably related to the factors set forth in section 3553(a)(1) and (a)(2) and to the extent that such conditions involve only such deprivations of liberty or property as are reasonably necessary for the purposes indicated in section 3553(a)(2), that the defendant—"],[1,"(1) support his dependents and meet other family responsibilities;"],[1,"(2) make restitution to a victim of the offense under section 3556 (but not subject to the limitation of section 3663(a) or 3663A(c)(1)(A));"],[1,"(3) give to the victims of the offense the notice ordered pursuant to the provisions of section 3555;"],[1,"(4) work conscientiously at suitable employment or pursue conscientiously a course of study or vocational training that will equip him for suitable employment;"],[1,"(5) refrain, in the case of an individual, from engaging in a specified occupation, business, or profession bearing a reasonably direct relationship to the conduct constituting the offense, or engage in such a specified occupation, business, or profession only to a stated degree or under stated circumstances;"],[1,"(6) refrain from frequenting specified kinds of places or from associating unnecessarily with specified persons;"],[1,"(7) refrain from excessive use of alcohol, or any use of a narcotic drug or other controlled substance, as defined in section 102 of the Controlled Substances Act (21 U.S.C. 802), without a prescription by a licensed medical practitioner;"],[1,"(8) refrain from possessing a firearm, destructive device, or other dangerous weapon;"],[1,"(9) undergo available medical, psychiatric, or psychological treatment, including treatment for drug or alcohol dependency, as specified by the court, and remain in a specified institution if required for that purpose;"],[1,"(10) remain in the custody of the Bureau of Prisons during nights, weekends, or other intervals of time, totaling no more than the lesser of one year or the term of imprisonment authorized for the offense, during the first year of the term of probation or supervised release;"],[1,"(11) reside at, or participate in the program of, a community corrections facility (including a facility maintained or under contract to the Bureau of Prisons) for all or part of the term of probation;"],[1,"(12) work in community service as directed by the court;"],[1,"(13) reside in a specified place or area, or refrain from residing in a specified place or area;"],[1,"(14) remain within the jurisdiction of the court, unless granted permission to leave by the court or a probation officer;"],[1,"(15) report to a probation officer as directed by the court or the probation officer;"],[1,"(16) permit a probation officer to visit him at his home or elsewhere as specified by the court;"],[1,"(17) answer inquiries by a probation officer and notify the probation officer promptly of any change in address or employment;"],[1,"(18) notify the probation officer promptly if arrested or questioned by a law enforcement officer;"],[1,"(19) remain at his place of residence during nonworking hours and, if the court finds it appropriate, that compliance with this condition be monitored by telephonic or electronic signaling devices, except that a condition under this paragraph may be imposed only as an alternative to incarceration;"],[1,"(20) comply with the terms of any court order or order of an administrative process pursuant to the law of a State, the District of Columbia, or any other possession or territory of the United States, requiring payments by the defendant for the support and maintenance of a child or of a child and the parent with whom the child is living;"],[1,"(21) be ordered deported by a United States district court, or United States magistrate judge, pursuant to a stipulation entered into by the defendant and the United States under section 238(d)(5) of the Immigration and Nationality Act, except that, in the absence of a stipulation, the United States district court or a United States magistrate judge, may order deportation as a condition of probation, if, after notice and hearing pursuant to such section, the Attorney General demonstrates by clear and convincing evidence that the alien is deportable;"],[1,"(22) satisfy such other conditions as the court may impose or; 1"],[1,"(23) if required to register under the Sex Offender Registration and Notification Act, submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communication or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of probation or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(c) Modifications of Conditions.—The court may modify, reduce, or enlarge the conditions of a sentence of probation at any time prior to the expiration or termination of the term of probation, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the conditions of probation."],[0,"(d) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the sentence is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(e) Results of Drug Testing.—The results of a drug test administered in accordance with subsection (a)(5) shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A defendant who tests positive may be detained pending verification of a positive drug test result. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3565(b), when considering any action against a defendant who fails a drug test administered in accordance with subsection (a)(5)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3563?type=usc&year=mostrecent&link-type=html"},"by":{"1":"17, 29, 35","2":"6"}},{"t":"usc","label":"18 U.S.C. § 3572","url":"https://www.law.cornell.edu/uscode/text/18/3572","subs":["(a)"],"stext":{"head":"§3572. Imposition of a sentence of fine and related matters","paras":[[0,"(a) Factors To Be Considered.—In determining whether to impose a fine, and the amount, time for payment, and method of payment of a fine, the court shall consider, in addition to the factors set forth in section 3553(a)—"],[1,"(1) the defendant's income, earning capacity, and financial resources;"],[1,"(2) the burden that the fine will impose upon the defendant, any person who is financially dependent on the defendant, or any other person (including a government) that would be responsible for the welfare of any person financially dependent on the defendant, relative to the burden that alternative punishments would impose;"],[1,"(3) any pecuniary loss inflicted upon others as a result of the offense;"],[1,"(4) whether restitution is ordered or made and the amount of such restitution;"],[1,"(5) the need to deprive the defendant of illegally obtained gains from the offense;"],[1,"(6) the expected costs to the government of any imprisonment, supervised release, or probation component of the sentence;"],[1,"(7) whether the defendant can pass on to consumers or other persons the expense of the fine; and"],[1,"(8) if the defendant is an organization, the size of the organization and any measure taken by the organization to discipline any officer, director, employee, or agent of the organization responsible for the offense and to prevent a recurrence of such an offense."],[0,"(b) Fine Not to Impair Ability to Make Restitution.—If, as a result of a conviction, the defendant has the obligation to make restitution to a victim of the offense, other than the United States, the court shall impose a fine or other monetary penalty only to the extent that such fine or penalty will not impair the ability of the defendant to make restitution."],[0,"(c) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to pay a fine can subsequently be—"],[1,"(1) modified or remitted under section 3573;"],[1,"(2) corrected under rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified under section 3742;"],[0,"a judgment that includes such a sentence is a final judgment for all other purposes."],[0,"(d) Time, Method of Payment, and Related Items.—(1) A person sentenced to pay a fine or other monetary penalty, including restitution, shall make such payment immediately, unless, in the interest of justice, the court provides for payment on a date certain or in installments. If the court provides for payment in installments, the installments shall be in equal monthly payments over the period provided by the court, unless the court establishes another schedule."],[0,"(2) If the judgment, or, in the case of a restitution order, the order, permits other than immediate payment, the length of time over which scheduled payments will be made shall be set by the court, but shall be the shortest time in which full payment can reasonably be made."],[0,"(3) A judgment for a fine which permits payments in installments shall include a requirement that the defendant will notify the court of any material change in the defendant's economic circumstances that might affect the defendant's ability to pay the fine. Upon receipt of such notice the court may, on its own motion or the motion of any party, adjust the payment schedule, or require immediate payment in full, as the interests of justice require."],[0,"(e) Alternative Sentence Precluded.—At the time a defendant is sentenced to pay a fine, the court may not impose an alternative sentence to be carried out if the fine is not paid."],[0,"(f) Responsibility for Payment of Monetary Obligation Relating to Organization.—If a sentence includes a fine, special assessment, restitution or other monetary obligation (including interest) with respect to an organization, each individual authorized to make disbursements for the organization has a duty to pay the obligation from assets of the organization. If such an obligation is imposed on a director, officer, shareholder, employee, or agent of an organization, payments may not be made, directly or indirectly, from assets of the organization, unless the court finds that such payment is expressly permissible under applicable State law."],[0,"(g) Security for Stayed Fine.—If a sentence imposing a fine is stayed, the court shall, absent exceptional circumstances (as determined by the court)—"],[1,"(1) require the defendant to deposit, in the registry of the district court, any amount of the fine that is due;"],[1,"(2) require the defendant to provide a bond or other security to ensure payment of the fine; or"],[1,"(3) restrain the defendant from transferring or dissipating assets."],[0,"(h) Delinquency.—A fine or payment of restitution is delinquent if a payment is more than 30 days late."],[0,"(i) Default.—A fine or payment of restitution is in default if a payment is delinquent for more than 90 days. Notwithstanding any installment schedule, when a fine or payment of restitution is in default, the entire amount of the fine or restitution is due within 30 days after notification of the default, subject to the provisions of section 3613A."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3572?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 27, 39","2":"7"},"q":[{"src":"brief","b":1,"text":"in addition to the factors set forth in section 3553(a),","cite":"18 U.S.C. 3572(a)"}]},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 27, 39","2":"7, 12, 13"},"q":[{"src":"brief","b":1,"text":"if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation.","cite":"18 U.S.C. 3582(a)"},{"src":"brief","b":1,"text":"consider the factors set forth in section 3553(a) * * * , recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation.","cite":"18 U.S.C. 3582(a)"}]},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(c)","(d)","(d)(2)","(e)","(e)(2)","(e)(3)","(e)(4)","(g)","(g)(1)","(g)(2)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 27, 39, 3, 27, 39, 17, 17, 17, 17, 17, 17, 17, 17, 21, 21, 21, 21","2":"1, 5, 6, 9, 1, 2, 6-14, 17, 18, 6, 16, 1-14, 17, 18, 8, 5-7, 11, 6, 7"},"q":[{"src":"brief","b":1,"text":"in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7).","cite":"18 U.S.C. 3583(c)"},{"src":"brief","b":1,"text":"may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7) * * * revoke a term of supervised release, and require the defendant to serve","cite":"18 U.S.C. 3583(e)(3)"}]},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"[n]o limitation shall be placed on the information concerning the background, character, and conduct of a person convicted of an offense which a court of the United States may receive and consider for the purpose of imposing an appropriate sentence.","cite":"18 U.S.C. 3661"}]},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","subs":["(a)(2)"],"by":{"1":"43"}},{"t":"usc","label":"18 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/18/401","subs":["(3)"],"by":{"1":"4, 39, 39"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(o)"],"by":{"1":"13"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)(2018)"],"by":{"1":"13"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)"],"by":{"1":"7, 12"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"1":"12"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)(3)","(c)(3)","(e)","(k)"],"by":{"1":"34, 31, 34, 34, 34, 34"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"rewrite clear statutes under the banner of [its] own policy concerns.","cite":"587 U.S. 566, 581"}]},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"2":"5"}},{"t":"case","label":"Gompers v. Bucks Stove & Range Co.","cite":"221 U.S. 418","y":1911,"id":"1900-1940/221us418","sc":1,"by":{"2":"17"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"Ultimately, the Government’s policy arguments do not obscure what the statutory language makes clear.","cite":"583 U.S. 109, 131"}]},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"by":{"2":"15"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"2":"9"}},{"t":"case","label":"United States v. Labonte","cite":"520 U.S. 751","y":1997,"id":"1996/95-1726","sc":1,"by":{"2":"15"}},{"t":"case","label":"United States v. Waffle","cite":"2023 WL 2964480","y":2023,"court":"10th Cir. Apr. 17","by":{"2":"15"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(g)"],"by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 3565","url":"https://www.law.cornell.edu/uscode/text/18/3565","subs":["(a)","(b)"],"by":{"2":"2, 3, 5-9, 6"}},{"t":"usc","label":"18 U.S.C. § 4246","url":"https://www.law.cornell.edu/uscode/text/18/4246","by":{"2":"17"}}]};